using ImportOps.Domain.Entities;
using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.Metadata.Builders;

namespace ImportOps.Infrastructure.Persistence.Configurations;

internal sealed class AlertRuleConfiguration:IEntityTypeConfiguration<AlertRule>{public void Configure(EntityTypeBuilder<AlertRule>b){b.ToTable("ALERT_RULE","cfg");b.HasKey(x=>x.AlertRuleId);b.Property(x=>x.AlertRuleId).HasColumnName("alert_rule_id");b.Property(x=>x.CompanyId).HasColumnName("company_id");b.Property(x=>x.AlertType).HasColumnName("alert_type");b.Property(x=>x.Name).HasColumnName("name");b.Property(x=>x.Description).HasColumnName("description");b.Property(x=>x.Severity).HasColumnName("severity");b.Property(x=>x.Audience).HasColumnName("audience");b.Property(x=>x.ThresholdHours).HasColumnName("threshold_hours");b.Property(x=>x.IsActive).HasColumnName("is_active");b.Property(x=>x.CreatedAt).HasColumnName("created_at");b.Property(x=>x.ModifiedAt).HasColumnName("modified_at");}}
internal sealed class AlertRecordConfiguration:IEntityTypeConfiguration<AlertRecord>{public void Configure(EntityTypeBuilder<AlertRecord>b){b.ToTable("ALERT","ops");b.HasKey(x=>x.AlertId);b.Property(x=>x.AlertId).HasColumnName("alert_id");b.Property(x=>x.CompanyId).HasColumnName("company_id");b.Property(x=>x.AlertRuleId).HasColumnName("alert_rule_id");b.Property(x=>x.AlertType).HasColumnName("alert_type");b.Property(x=>x.Severity).HasColumnName("severity");b.Property(x=>x.Audience).HasColumnName("audience");b.Property(x=>x.OperationId).HasColumnName("operation_id");b.Property(x=>x.ClientId).HasColumnName("client_id");b.Property(x=>x.ResponsibleUserId).HasColumnName("responsible_user_id");b.Property(x=>x.RequiredPermission).HasColumnName("required_permission");b.Property(x=>x.Title).HasColumnName("title");b.Property(x=>x.Message).HasColumnName("message");b.Property(x=>x.SourceType).HasColumnName("source_type");b.Property(x=>x.SourceId).HasColumnName("source_id");b.Property(x=>x.ActionPath).HasColumnName("action_path");b.Property(x=>x.DedupKey).HasColumnName("dedup_key");b.Property(x=>x.Status).HasColumnName("status");b.Property(x=>x.TriggeredAt).HasColumnName("triggered_at");b.Property(x=>x.LastDetectedAt).HasColumnName("last_detected_at");b.Property(x=>x.ResolvedAt).HasColumnName("resolved_at");b.Property(x=>x.CreatedAt).HasColumnName("created_at");b.Property(x=>x.ModifiedAt).HasColumnName("modified_at");}}
internal sealed class AlertUserStateConfiguration:IEntityTypeConfiguration<AlertUserState>{public void Configure(EntityTypeBuilder<AlertUserState>b){b.ToTable("ALERT_USER_STATE","ops");b.HasKey(x=>new{x.AlertId,x.UserId});b.Property(x=>x.AlertId).HasColumnName("alert_id");b.Property(x=>x.UserId).HasColumnName("user_id");b.Property(x=>x.IsRead).HasColumnName("is_read");b.Property(x=>x.ReadAt).HasColumnName("read_at");b.Property(x=>x.IsDismissed).HasColumnName("is_dismissed");b.Property(x=>x.DismissedAt).HasColumnName("dismissed_at");}}
